import { PlaneGeometry, MeshBasicNodeMaterial, Texture } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, texture, min, float, distance } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const Group = THREE.Group;

  const group = new Group();
  group.name = 'collection-card-3';

  // colors from spec
  const INK = new THREE.Color('#16161d');
  const SURFACE = new THREE.Color('#0b0b10');
  const ACCENT = new THREE.Color('#ff2a38');

  // atlas rect 512x320 -> aspect 1.6
  const aspect = 512 / 320;
  const cardWidth = 1.6;
  const cardHeight = cardWidth / aspect;

  // ---- backdrop frame (slightly larger, ink tone) for depth separation ----
  const frameGeo = new PlaneGeometry(cardWidth * 1.06, cardHeight * 1.1);
  const frameMat = new MeshBasicNodeMaterial({ transparent: true });
  frameMat.colorNode = vec3(INK.r * 0.7, INK.g * 0.7, INK.b * 0.7);
  frameMat.opacityNode = float(0.9);
  const frameMesh = new THREE.Mesh(frameGeo, frameMat);
  frameMesh.position.z = -0.02;
  group.add(frameMesh);

  // ---- contact shadow plane (grounded object) ----
  const shadowRadius = cardWidth * 1.35;
  const shadowGeo = new PlaneGeometry(shadowRadius, shadowRadius * 0.7);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const shadowUv = uv();
  const shadowDist = distance(shadowUv, vec2(0.5, 0.5));
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = smoothstep(0.5, 0.0, shadowDist).mul(0.45);
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -cardHeight * 0.62, -0.03);
  group.add(shadowMesh);

  // ---- main card surface: engineered gradient + subtle grain ----
  const placeholderTex = new Texture();
  const cardGeo = new PlaneGeometry(cardWidth, cardHeight);
  const cardMat = new MeshBasicNodeMaterial({ transparent: false });

  const cardUv = uv();

  // engineered vertical gradient: ink (top) -> surface (bottom)
  const gradient = mix(
    vec3(SURFACE.r, SURFACE.g, SURFACE.b),
    vec3(INK.r, INK.g, INK.b),
    smoothstep(0.0, 1.0, cardUv.y)
  );

  // grain texture (multiplicative, subtle strength)
  const grainTex = texture(placeholderTex, cardUv);
  const grained = gradient.mul(mix(vec3(1.0, 1.0, 1.0), grainTex.rgb, 0.28));

  // thin machined accent border along edges (<=10% of frame area)
  const distX = min(cardUv.x, float(1.0).sub(cardUv.x));
  const distY = min(cardUv.y, float(1.0).sub(cardUv.y));
  const distToEdge = min(distX, distY);
  const borderMask = smoothstep(0.018, 0.0, distToEdge);

  const finalColor = mix(grained, vec3(ACCENT.r, ACCENT.g, ACCENT.b), borderMask.mul(0.55));
  cardMat.colorNode = finalColor;

  const cardMesh = new THREE.Mesh(cardGeo, cardMat);
  group.add(cardMesh);

  // load grain texture async through ctx loader, apply once ready
  let disposed = false;
  const texPromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      if (disposed) return;
      grainTex.value = tex;
      cardMat.needsUpdate = true;
    })
    .catch(() => {});

  // entrance: weighted-settle (subject scale + slight rise, no linear easing)
  group.scale.setScalar(0.96);
  group.position.y -= 0.08;
  const tl = gsap.timeline();
  tl.to(group.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' });
  tl.to(group.position, { y: group.position.y + 0.08, duration: 0.9, ease: 'power4.out' }, 0);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    disposed = true;
    tl.kill();
    frameGeo.dispose();
    frameMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    cardGeo.dispose();
    cardMat.dispose();
    placeholderTex.dispose();
    if (grainTex.value && grainTex.value.dispose) {
      grainTex.value.dispose();
    }
  };

  return group;
}
